Item.method_code:
/*
    帳票マスタの配下の開達書式が全てアンロックかどうかを確認
    承認後の開達書式のプロパティ変更のためにあらかじめ確認する（LCのPostで実装）
*/
Innovator inn = getInnovator();

//配下の検索
using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
    // WFアイテムから対象アイテム取得
    Item ctrlItem = inn.newItem("Method", "h4_GetControlledItem");
    ctrlItem.setID(this.getID());
    ctrlItem = ctrlItem.apply();
    if(ctrlItem.isError())
    {
        //エラー
        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
    }
    
    //帳票マスタ以外は処理なし
    if(ctrlItem.getType() != "h4_DATMaster")
    {
        return　this;
    }
    
    
    // 動作部分呼び出し
    Item callMethod1 = inn.newItem("Method", "h4_CheckIsLockRelatedDAT_Core");
    callMethod1.setID(ctrlItem.getID());
    callMethod1 = callMethod1.apply();
    if(callMethod1.isError())
    {
        //エラー
        return inn.newError(callMethod1.getErrorString());
    }
}

return　this;
